#!/bin/bash
# bench.sh LOG ROUND UNIT CONFIG...: benchmark-checker-deferred on one unit, one process per configuration, each
# process's heading, output and exit status appended to LOG. queue.sh runs it inside one lock hold.
#
# UNIT: cts/NAME.c (c-testsuite's single-exec program), sqlite (the frozen sqlite3.c), syn/NAME.c (one of the 38
# synthetic units of the deferred-lane-costs-113-2026-10-27 record, regenerated by its gen2.c) or musl/PATH.c (the
# frozen musl's src/PATH.c). The c-testsuite programs, the synthetic units and SQLite take the frozen corpus's pinned
# GNU17 options, as #448's, #683's and the 9700X job's runs do; musl takes its build's (config/musl.args without -E's
# own flags).
#
# CONFIG: MODE:L, with --lanes L. MODE is `rule` (the reader's rule, at most L lanes), `every` (--every-lane: every
# lane the bodies can take, at most L), or `rss-rule`/`rss-every`, the same with --rss --cold and 6 passes, whose
# times aren't used. Every process has --raw and --cpus 2,0,1,3,4,5,6,7. A configuration TREE+MODE:L runs the build in
# TREE (a directory beside tree/, e.g. cand+rule:8) instead of tree/'s.
set -u
D=~/buster-fast-bench/447-claude
C=/var/lib/buster-9700x/corpora/preprocessor-391e729af658
M=$C/libc/musl
log=$1
round=$2
unit=$3
shift 3
gnu17=(--predefines "$C/provenance/gnu17-pinned-predefines.txt" --clang-features --no-default-config --target=x86_64-linux-gnu -march=znver5 -std=gnu17 -nostdinc -isystem "$C/headers/usr/lib/clang/23/include" -isystem "$C/headers/usr/local/include" -isystem "$C/headers/usr/include")
musl=(--clang-features --no-default-config --target=x86_64-linux-gnu -march=znver5 -std=c99 -ffreestanding -nostdinc -D_XOPEN_SOURCE=700 -Os -I "$M/arch/x86_64" -I "$M/arch/generic" -I "$C/musl-generated/obj/src/internal" -I "$M/src/include" -I "$M/src/internal" -I "$C/musl-generated/obj/include" -I "$M/include")
case "$unit" in
    cts/*)
        file="$D/c-testsuite/tests/single-exec/${unit#cts/}"
        passes=24
        options=("${gnu17[@]}")
        ;;
    sqlite)
        file="$C/sqlite/sqlite3.c"
        passes=12
        options=("${gnu17[@]}")
        ;;
    syn/*)
        file="$D/synthetic/${unit#syn/}"
        passes=24
        options=("${gnu17[@]}")
        ;;
    musl/*)
        file="$M/src/${unit#musl/}"
        passes=24
        options=("${musl[@]}")
        ;;
    *)
        echo "bench.sh: unknown unit $unit" >> "$log"
        exit 1
        ;;
esac
unset CPATH C_INCLUDE_PATH
export SOURCE_DATE_EPOCH=1792454400
for config in "$@"; do
    tree=tree
    setting=$config
    if [[ $config == *+* ]]; then
        tree=${config%%+*}
        setting=${config#*+}
    fi
    IFS=: read -r mode lanes <<< "$setting"
    extra=()
    run_passes=$passes
    case "$mode" in
        rule) ;;
        every) extra=(--every-lane) ;;
        rss-rule) extra=(--rss --cold); run_passes=6 ;;
        rss-every) extra=(--rss --cold --every-lane); run_passes=6 ;;
        *) echo "bench.sh: unknown mode $mode" >> "$log"; continue ;;
    esac
    echo "== round $round unit $unit config $config $(date -Is)" >> "$log"
    "$D/$tree/build/compiler" benchmark-checker-deferred --passes "$run_passes" --lanes "$lanes" --cpus 2,0,1,3,4,5,6,7 --raw "${extra[@]}" "${options[@]}" "$file" >> "$log" 2>&1
    echo "exit=$? $(date -Is)" >> "$log"
done
